func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealthz)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readyz", wrapper.GetReadyz)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/cis/notifications", wrapper.ReceiveCISNotification)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/registry/validate", wrapper.ValidateRegistry)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/intents", wrapper.ListIntents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/intents", wrapper.CreateIntent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/intents/{intent_id}", wrapper.GetIntent)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/intents/{intent_id}", wrapper.ChangeIntent)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/geo", wrapper.GetGeo)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/geo/intents/{intent_id}", wrapper.GetGeoForIntent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/alerts/{alert_id}/ack", wrapper.AckAlert)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/admin/coordination", wrapper.ListCoordinationNotices)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/records/flights/{flight_id}", wrapper.GetFlightRecord)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/records/daily/{date}", wrapper.GetDailyRecords)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/oauth/token", wrapper.RequestToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/.well-known/jwks.json", wrapper.GetJWKS)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/accounts/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/operators", wrapper.RegisterOperator)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}", wrapper.GetOperator)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}", wrapper.UpdateOperator)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}/clients", wrapper.CreateClient)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}/clients/{client_id}/rotate", wrapper.RotateClientSecret)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}/clients/{client_id}/serials", wrapper.BindSerial)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/accounts/operators/{operator_id}/clients/{client_id}/serials/{serial}", wrapper.UnbindSerial)

	return m
}
